contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Send an arbitrary amount to c.go. We require this contract has enough balance
    // so the call can forward `amount` when invoked by the checker.
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // Observe owner and this contract balance before the call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = address(this).balance;

        // Perform the call and record whether it reverted
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe owner and this contract balance after the call
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceAfter = address(this).balance;

        // General invariant:
        // - owner never changes
        // - if the call did not revert then the caller's balance after the call is >= balanceBefore - amount
        //   (i.e., the call cannot reduce the caller's balance by more than the forwarded amount)
        assert(ownerBefore == ownerAfter && (reverted || balanceAfter + amount >= balanceBefore));
    }

    receive() external payable {}
}

